"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[796],{6696(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"part2-backend-platform-security/external-service-integration","title":"Calling External Services Across Cloud Trust Boundaries","description":"A GCP workload calling Azure OpenAI needs an Azure-accepted credential, a bounded network client, and a clear data-governance contract.","source":"@site/docs/part2-backend-platform-security/13-external-service-integration.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/13-external-service-integration","permalink":"/tutorials/part2-backend-platform-security/13-external-service-integration","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":13,"frontMatter":{"title":"Calling External Services Across Cloud Trust Boundaries","slug":"/part2-backend-platform-security/13-external-service-integration","description":"A GCP workload calling Azure OpenAI needs an Azure-accepted credential, a bounded network client, and a clear data-governance contract.","sidebar_label":"15. Cross-cloud service integration","pagination_label":"15. Cross-cloud service integration","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"14. GCP workload identity","permalink":"/tutorials/part2-backend-platform-security/11-gcp-workload-identity"},"next":{"title":"16. GitHub governance and CI","permalink":"/tutorials/part2-backend-platform-security/14-github-governance"}}');var o=n(4848),a=n(8453),i=n(8172);const s=JSON.parse('{"sourcePath":"part2-backend-platform-security/13-external-service-integration.html","route":"/part2-backend-platform-security/13-external-service-integration","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Calling External Services Across Cloud Trust Boundaries","title":"Calling External Services Across Cloud Trust Boundaries","description":"A GCP workload calling Azure OpenAI needs an Azure-accepted credential, a bounded network client, and a clear data-governance contract.","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-option-a-api-key-stored-in-gcp-secret-manager","label":"1. Option A: API Key Stored in GCP Secret Manager"},{"id":"2-option-b-microsoft-entra-workload-identity-federation","label":"2. Option B: Microsoft Entra Workload Identity Federation"},{"id":"3-how-this-relates-to-service-accounts","label":"3. How This Relates to Service Accounts"},{"id":"4-reliability-rules-shared-by-both-options","label":"4. Reliability Rules Shared by Both Options"},{"id":"5-data-governance-and-observability","label":"5. Data Governance and Observability"},{"id":"6-decision-summary","label":"6. Decision Summary"},{"id":"official-references","label":"Official References"}],"html":"<p class=\\"lead\\">A GCP workload calling Azure OpenAI needs an Azure-accepted credential, a bounded network client, and a clear data-governance contract.</p>\\n\\n    <div class=\\"tr-note\\">\\n        <strong>Where this fits</strong>\\n        Chapter 12 separated end-user identity, application authorization,\\n        and workload identity. This chapter follows the workload across a\\n        cloud boundary. The end user\'s bearer token still authorizes the\\n        application request, but the backend uses its own credential to call\\n        Azure.\\n    </div>\\n\\n    <figure class=\\"figure-card\\">\\n        <svg viewBox=\\"0 0 1040 390\\" role=\\"img\\" aria-labelledby=\\"cross-cloud-title cross-cloud-desc\\">\\n            <title id=\\"cross-cloud-title\\">Two supported authentication paths from GCP to Azure OpenAI</title>\\n            <desc id=\\"cross-cloud-desc\\">A GKE workload can read an API key from Secret Manager or exchange a Google-issued workload token with Microsoft Entra. Either credential is then used to call Azure OpenAI.</desc>\\n            <defs>\\n                <marker id=\\"cross-arrow-blue\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n                    <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n                </marker>\\n                <marker id=\\"cross-arrow-green\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n                    <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#14875a\\"></path>\\n                </marker>\\n            </defs>\\n\\n            <rect x=\\"35\\" y=\\"135\\" width=\\"190\\" height=\\"110\\" rx=\\"14\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"130\\" y=\\"176\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">GKE backend</text>\\n            <text x=\\"130\\" y=\\"207\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">Google workload identity</text>\\n\\n            <rect x=\\"335\\" y=\\"35\\" width=\\"240\\" height=\\"105\\" rx=\\"14\\" fill=\\"#fff6df\\" stroke=\\"#bf8700\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"455\\" y=\\"75\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">GCP Secret Manager</text>\\n            <text x=\\"455\\" y=\\"106\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">versioned Azure API key</text>\\n\\n            <rect x=\\"335\\" y=\\"250\\" width=\\"240\\" height=\\"105\\" rx=\\"14\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"455\\" y=\\"290\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Microsoft Entra ID</text>\\n            <text x=\\"455\\" y=\\"321\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">federated token exchange</text>\\n\\n            <rect x=\\"730\\" y=\\"135\\" width=\\"270\\" height=\\"110\\" rx=\\"14\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"865\\" y=\\"176\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Azure OpenAI</text>\\n            <text x=\\"865\\" y=\\"207\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">API key or Entra bearer token</text>\\n\\n            <path d=\\"M225 165 C270 125 285 88 335 88\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#cross-arrow-blue)\\"></path>\\n            <path d=\\"M575 88 C650 88 655 160 730 170\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#cross-arrow-blue)\\"></path>\\n            <path d=\\"M225 215 C270 260 285 302 335 302\\" fill=\\"none\\" stroke=\\"#7548d8\\" stroke-width=\\"3\\" marker-end=\\"url(#cross-arrow-blue)\\"></path>\\n            <path d=\\"M575 302 C650 302 655 220 730 210\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#cross-arrow-green)\\"></path>\\n\\n            <text x=\\"270\\" y=\\"114\\" font-size=\\"13\\" fill=\\"#1769e0\\">read secret</text>\\n            <text x=\\"604\\" y=\\"117\\" font-size=\\"13\\" fill=\\"#1769e0\\">api-key</text>\\n            <text x=\\"246\\" y=\\"286\\" font-size=\\"13\\" fill=\\"#7548d8\\">external assertion</text>\\n            <text x=\\"610\\" y=\\"278\\" font-size=\\"13\\" fill=\\"#14875a\\">short-lived token</text>\\n        </svg>\\n        <figcaption>\\n            The two paths solve the same authentication problem with different\\n            operational tradeoffs. Neither sends the end user\'s token to\\n            Azure as the backend credential.\\n        </figcaption>\\n    </figure>\\n\\n    <p>There are two production patterns. Choose from policy and operational requirements rather than assuming that the most complex option is always best.</p>\\n\\n    <table>\\n        <thead>\\n            <tr><th>Question</th><th>API key in Secret Manager</th><th>Entra workload federation</th></tr>\\n        </thead>\\n        <tbody>\\n            <tr><td>Long-lived Azure credential</td><td>Yes; rotate and version it.</td><td>No; exchange a trusted external assertion for a short-lived token.</td></tr>\\n            <tr><td>Initial setup</td><td>Lower.</td><td>Higher: app registration, federated credential, RBAC, and token exchange.</td></tr>\\n            <tr><td>Runtime dependencies</td><td>GCP IAM + Secret Manager + Azure endpoint.</td><td>Google token issuer + Entra token endpoint + Azure endpoint.</td></tr>\\n            <tr><td>Best fit</td><td>Smaller systems with mature secret rotation.</td><td>Higher-assurance systems that prohibit static cross-cloud credentials.</td></tr>\\n        </tbody>\\n    </table>\\n\\n    <div class=\\"section-divider\\"></div>\\n\\n    <h2 id=\\"1-option-a-api-key-stored-in-gcp-secret-manager\\">1. Option A: API Key Stored in GCP Secret Manager</h2>\\n\\n    <h3 id=\\"flow\\">Flow</h3>\\n    <ol>\\n        <li>Your backend (running on GKE) authenticates to GCP Secret Manager using its GCP service account (Workload Identity).</li>\\n        <li>It reads the Azure OpenAI API key from Secret Manager.</li>\\n        <li>It calls Azure OpenAI with:\\n            <ul>\\n                <li><code>api-key: &lt;key&gt;</code> header (typical for Azure OpenAI)</li>\\n            </ul>\\n        </li>\\n    </ol>\\n\\n    <h3 id=\\"why-choose-this\\">Why choose this</h3>\\n    <ul>\\n        <li>Easiest to implement</li>\\n        <li>No Azure identity federation complexity</li>\\n        <li>Common and reliable</li>\\n    </ul>\\n\\n    <h3 id=\\"what-you-associate\\">What you \u201cassociate\u201d</h3>\\n\\n    <h4>1) Store the secret</h4>\\n    <ul>\\n        <li>Secret: <code>azure-openai-api-key</code></li>\\n    </ul>\\n\\n    <h4>2) Grant your backend service account access to read it</h4>\\n    <ul>\\n        <li>IAM: give <code>backend-sa@...</code> role <code>roles/secretmanager.secretAccessor</code> on that secret.</li>\\n    </ul>\\n\\n    <h4>3) In code: load once, reuse the HTTP client, and call Azure</h4>\\n\\n    <pre><code class=\\"language-python\\">import os\\nfrom contextlib import asynccontextmanager\\n\\nimport httpx\\nfrom fastapi import FastAPI, Request\\nfrom google.cloud import secretmanager\\n\\n\\ndef read_secret(secret_id: str, version: str) -&gt; str:\\n    client = secretmanager.SecretManagerServiceClient()\\n    name = (\\n        f\\"projects/{os.environ[\'GCP_PROJECT\']}/secrets/\\"\\n        f\\"{secret_id}/versions/{version}\\"\\n    )\\n    response = client.access_secret_version(request={\\"name\\": name})\\n    return response.payload.data.decode(\\"utf-8\\")\\n\\n\\nclass AzureOpenAIClient:\\n    def __init__(self, *, api_key: str, endpoint: str, deployment: str):\\n        self._deployment = deployment\\n        self._http = httpx.AsyncClient(\\n            base_url=endpoint.rstrip(\\"/\\"),\\n            headers={\\"api-key\\": api_key},\\n            timeout=httpx.Timeout(connect=5.0, read=60.0, write=15.0, pool=5.0),\\n            limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),\\n        )\\n\\n    async def create_response(self, prompt: str) -&gt; dict:\\n        response = await self._http.post(\\n            \\"/openai/v1/responses\\",\\n            json={\\"model\\": self._deployment, \\"input\\": prompt},\\n        )\\n        response.raise_for_status()\\n        return response.json()\\n\\n    async def close(self) -&gt; None:\\n        await self._http.aclose()\\n\\n\\n@asynccontextmanager\\nasync def lifespan(app: FastAPI):\\n    # Secret access is synchronous, but startup completes before requests run.\\n    # Pin a deployed version so rollback is deterministic.\\n    api_key = read_secret(\\n        \\"azure-openai-api-key\\",\\n        os.environ[\\"AZURE_OPENAI_KEY_VERSION\\"],\\n    )\\n    app.state.azure_openai = AzureOpenAIClient(\\n        api_key=api_key,\\n        endpoint=os.environ[\\"AZURE_OPENAI_ENDPOINT\\"],\\n        deployment=os.environ[\\"AZURE_OPENAI_DEPLOYMENT\\"],\\n    )\\n    yield\\n    await app.state.azure_openai.close()\\n\\n\\napp = FastAPI(lifespan=lifespan)\\n\\n\\n@app.post(\\"/generate\\")\\nasync def generate(request: Request, prompt: str) -&gt; dict:\\n    return await request.app.state.azure_openai.create_response(prompt)</code></pre>\\n\\n    <p class=\\"callout warn\\">\\n        Microsoft Foundry exposes several API surfaces. The example uses the\\n        current OpenAI-compatible <code>/openai/v1/responses</code> shape.\\n        Older\\n        deployment-scoped routes use an explicit <code>api-version</code>\\n        query parameter. Treat endpoint paths, supported models, and API\\n        versions as deployed configuration checked against the current Azure\\n        documentation.\\n    </p>\\n\\n    <p>\\n        Reading Secret Manager on every model call adds latency and another\\n        failure point. Load a pinned version at startup, inject a mounted\\n        secret through your platform, or use a controlled refresh mechanism.\\n        Rotate by creating a new secret version, deploying the new version\\n        reference, verifying it, and then disabling the old version.\\n    </p>\\n\\n    <div class=\\"section-divider\\"></div>\\n\\n    <h2 id=\\"2-option-b-microsoft-entra-workload-identity-federation\\">2. Option B: Microsoft Entra Workload Identity Federation</h2>\\n\\n    <h3 id=\\"flow-2\\">Flow</h3>\\n    <ol>\\n        <li>Your backend runs as a specific Kubernetes/Google service account through Workload Identity Federation for GKE.</li>\\n        <li>The workload obtains a Google-signed OIDC assertion with the audience expected by the Entra federated credential.</li>\\n        <li>Microsoft Entra validates the assertion\'s issuer, subject, audience, and signature against the configured trust.</li>\\n        <li>The workload exchanges that assertion for a short-lived Entra access token scoped to Azure AI.</li>\\n        <li>It calls Azure OpenAI with <code>Authorization: Bearer &lt;access_token&gt;</code>.</li>\\n    </ol>\\n\\n    <h3 id=\\"what-must-be-configured\\">What must be configured</h3>\\n    <ol>\\n        <li>Create an Entra app registration (or supported managed identity) and its service principal.</li>\\n        <li>Add a federated identity credential whose <code>issuer</code>, <code>subject</code>, and <code>audience</code> exactly match the Google assertion. Microsoft\'s Google Cloud example uses issuer <code>https://accounts.google.com</code>, the Google service account\'s unique ID as subject, and <code>api://AzureADTokenExchange</code> as audience.</li>\\n        <li>Assign only the Azure role required for inference, commonly <code>Cognitive Services OpenAI User</code>, at the narrowest useful scope.</li>\\n        <li>Configure the workload with the Entra tenant ID, application client ID, Azure scope, endpoint, and model deployment; none of these values is a secret.</li>\\n    </ol>\\n\\n    <pre><code class=\\"language-python\\"># Protocol-level outline. Production code should use a supported credential\\n# library or a well-tested exchange component rather than duplicating OAuth.\\nexternal_assertion = obtain_google_oidc_assertion(\\n    audience=\\"api://AzureADTokenExchange\\"\\n)\\n\\ntoken_response = await http.post(\\n    f\\"https://login.microsoftonline.com/{tenant_id}/oauth2/v2.0/token\\",\\n    data={\\n        \\"client_id\\": entra_client_id,\\n        \\"grant_type\\": \\"client_credentials\\",\\n        \\"scope\\": \\"https://cognitiveservices.azure.com/.default\\",\\n        \\"client_assertion_type\\": (\\n            \\"urn:ietf:params:oauth:client-assertion-type:jwt-bearer\\"\\n        ),\\n        \\"client_assertion\\": external_assertion,\\n    },\\n)\\ntoken_response.raise_for_status()\\nazure_access_token = token_response.json()[\\"access_token\\"]\\n\\nresult = await http.post(\\n    f\\"{azure_endpoint}/openai/v1/responses\\",\\n    headers={\\"Authorization\\": f\\"Bearer {azure_access_token}\\"},\\n    json={\\"model\\": deployment, \\"input\\": prompt},\\n)</code></pre>\\n\\n    <h3 id=\\"why-choose-this-2\\">Why choose this</h3>\\n    <ul>\\n        <li>No long-lived API keys</li>\\n        <li>Short-lived tokens, easier to rotate</li>\\n        <li>Stronger enterprise security posture</li>\\n    </ul>\\n\\n    <h3 id=\\"tradeoffs\\">Tradeoffs</h3>\\n    <ul>\\n        <li>More setup (Azure app registration, federated identity config, token exchange logic)</li>\\n        <li>Slightly more moving parts than API keys</li>\\n    </ul>\\n\\n    <div class=\\"section-divider\\"></div>\\n\\n    <h2 id=\\"3-how-this-relates-to-service-accounts\\">3. How This Relates to Service Accounts</h2>\\n\\n    <p><strong>Important:</strong></p>\\n    <ul>\\n        <li>Your GCP service account gives you permission to read GCP secrets/logs/etc.</li>\\n        <li>Azure doesn\u2019t care about GCP service accounts. Azure cares about Azure identity (or API keys).</li>\\n        <li>So you either:\\n            <ul>\\n                <li>use GCP SA \u2192 read API key \u2192 call Azure (Option A), or</li>\\n                <li>configure federation so your workload can mint Azure tokens (Option B)</li>\\n            </ul>\\n        </li>\\n    </ul>\\n\\n    <div class=\\"section-divider\\"></div>\\n\\n    <h2 id=\\"4-reliability-rules-shared-by-both-options\\">4. Reliability Rules Shared by Both Options</h2>\\n    <ul>\\n        <li><strong>Reuse clients and connections:</strong> create one bounded HTTP client per process, not one client per request.</li>\\n        <li><strong>Set phase-specific timeouts:</strong> connect, pool acquisition, write, and read can fail for different reasons.</li>\\n        <li><strong>Retry selectively:</strong> retry connection failures, selected <code>429</code> responses, and selected <code>5xx</code> responses with server guidance, exponential backoff, jitter, and a strict attempt budget. Do not retry ordinary <code>400</code>/<code>401</code>/<code>403</code> errors unchanged.</li>\\n        <li><strong>Bound concurrency:</strong> use connection limits, rate limits, and admission control so Azure throttling does not become an internal retry storm.</li>\\n        <li><strong>Preserve deadlines:</strong> an outbound timeout must fit inside the remaining inbound request deadline.</li>\\n        <li><strong>Make effects idempotent:</strong> model inference is normally read-like, but tool calls or downstream writes triggered from a response need explicit idempotency controls.</li>\\n    </ul>\\n\\n    <h2 id=\\"5-data-governance-and-observability\\">5. Data Governance and Observability</h2>\\n    <p>\\n        Authentication answers whether the workload may call Azure. It does\\n        not decide whether the prompt may contain a customer\'s data. Before\\n        crossing the boundary, classify the payload and enforce residency,\\n        retention, encryption, private networking/egress, content logging,\\n        and contractual requirements.\\n    </p>\\n    <ul>\\n        <li>Send only the fields required for the model task; redact secrets and unnecessary personal data.</li>\\n        <li>Log request IDs, tenant IDs, deployment names, token counts, latency, status class, retry count, and policy decisions, but never credentials or full sensitive prompts by default.</li>\\n        <li>Separate caller authorization from provider credentials in traces so audit records show both the initiating user and executing workload.</li>\\n        <li>Alert on authentication failures, sustained throttling, latency percentiles, model/deployment drift, and unusual per-tenant usage.</li>\\n    </ul>\\n\\n    <h2 id=\\"6-decision-summary\\">6. Decision Summary</h2>\\n    <div class=\\"tr-tip\\">\\n        <strong>Choose the simplest option that satisfies policy</strong>\\n        Use a versioned Secret Manager API key when your organization accepts\\n        managed static credentials and can rotate them reliably. Use Entra\\n        federation when eliminating long-lived cross-cloud secrets justifies\\n        the extra trust configuration and token-exchange dependency.\\n    </div>\\n\\n    <h2 id=\\"official-references\\">Official References</h2>\\n    <ul>\\n        <li><a href=\\"https://learn.microsoft.com/en-us/entra/workload-id/workload-identity-federation-create-trust\\">Microsoft Entra: create trust with an external identity provider</a></li>\\n        <li><a href=\\"https://learn.microsoft.com/en-us/rest/api/microsoft-foundry/azureopenai/responses\\">Microsoft Foundry Models: Responses REST reference</a></li>\\n        <li><a href=\\"https://learn.microsoft.com/en-gb/azure/foundry/openai/how-to/responses\\">Microsoft Foundry: use the Responses API</a></li>\\n        <li><a href=\\"https://docs.cloud.google.com/secret-manager/docs/best-practices\\">Google Cloud Secret Manager best practices</a></li>\\n    </ul>"}'),l={title:"Calling External Services Across Cloud Trust Boundaries",slug:"/part2-backend-platform-security/13-external-service-integration",description:"A GCP workload calling Azure OpenAI needs an Azure-accepted credential, a bounded network client, and a clear data-governance contract.",sidebar_label:"15. Cross-cloud service integration",pagination_label:"15. Cross-cloud service integration",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},u=[];function p(e){return(0,o.jsx)(i.A,{content:s})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(p,{...e})}):p()}}}]);